  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "medium",
    "touches": ["rpc_api", "other"],
    "why": "Mistakes in index pruning checks or error reporting could cause RPC or REST callers to receive false transaction misses or fail to locate transactions during chain reorganizations."
  }
}
